const cfg = $('Config').first().json.config;
const leads = $input.first().json.leads || [];

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const when = (iso) => (iso ? new Date(iso).toISOString().replace('T', ' ').slice(0, 16) + ' UTC' : '');

const colors = { hot: '#d64545', warm: '#e8a33d', cold: '#4a90d9', spam: '#9aa5b1' };
const badge = (text, color) =>
  `<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:12px;color:#fff;background:${color}">${esc(text)}</span>`;

const count = (key, value) => leads.filter((l) => l[key] === value).length;
const tiles = [
  ['Total leads', leads.length, '#1f2933'],
  ['Hot', count('category', 'hot'), colors.hot],
  ['Warm', count('category', 'warm'), colors.warm],
  ['Cold', count('category', 'cold'), colors.cold],
  ['Spam', count('category', 'spam'), colors.spam],
  ['Meetings requested', count('status', 'meeting_requested'), '#2f9e6f'],
].map(([label, value, color]) => `
  <div style="flex:1 1 120px;background:#fff;border-radius:8px;padding:14px 16px;box-shadow:0 1px 2px rgba(0,0,0,.06)">
    <div style="font-size:12px;color:#7b8794">${label}</div>
    <div style="font-size:26px;font-weight:bold;color:${color}">${value}</div>
  </div>`).join('');

const rows = leads.map((l) => `
  <tr>
    <td>${esc(l.id)}</td>
    <td><strong>${esc(l.full_name)}</strong><br><span class="muted">${esc(l.email)}</span></td>
    <td>${esc(l.company)}</td>
    <td>${l.category ? badge(l.category, colors[l.category] || '#7b8794') : ''}</td>
    <td>${esc(l.score)}</td>
    <td>${esc(String(l.status || '').replace(/_/g, ' '))}</td>
    <td>${esc(l.owner_email)}</td>
    <td>${Number(l.follow_up_step) >= 0 ? esc(l.follow_up_step) : 'not started'}${l.next_follow_up_at ? `<br><span class="muted">next ${esc(when(l.next_follow_up_at))}</span>` : ''}</td>
    <td class="muted">${esc(l.classified_by === 'llm' ? 'AI' : l.classified_by)}</td>
    <td style="max-width:320px">${esc(l.summary)}</td>
    <td class="muted">${esc(when(l.created_at))}</td>
  </tr>`).join('');

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(cfg.companyName)} CRM</title>
<style>
  body { font-family: Arial, Helvetica, sans-serif; background: #f5f7fa; color: #1f2933; margin: 0; padding: 24px 16px; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  .muted { color: #7b8794; font-size: 12px; }
  .wrap { overflow-x: auto; background: #fff; border-radius: 8px; box-shadow: 0 1px 2px rgba(0,0,0,.06); }
  table { border-collapse: collapse; width: 100%; font-size: 14px; }
  th, td { text-align: left; padding: 10px 12px; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
  th { background: #f0f2f5; font-size: 12px; text-transform: uppercase; letter-spacing: .04em; color: #52606d; }
</style></head>
<body>
  <h1>${esc(cfg.companyName)} lead pipeline</h1>
  <p class="muted">Newest first. Refresh to see new leads and follow-ups.</p>
  <div style="display:flex;flex-wrap:wrap;gap:12px;margin:16px 0">${tiles}</div>
  <div class="wrap"><table>
    <thead><tr><th>#</th><th>Lead</th><th>Company</th><th>Category</th><th>Score</th><th>Status</th>
    <th>Owner</th><th>Follow-up</th><th>By</th><th>Summary</th><th>Created</th></tr></thead>
    <tbody>${rows || '<tr><td colspan="11" class="muted">No leads yet. Run: bash scripts/send-sample-leads.sh</td></tr>'}</tbody>
  </table></div>
</body></html>`;

return [{ json: { html } }];
